function moveFocus(dx,dy){var options=focusables(),current=document.activeElement,r=current.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,best=null,score=Infinity;options.forEach(function(el){if(el===current)return;var b=el.getBoundingClientRect(),x=b.left+b.width/2-cx,y=b.top+b.height/2-cy;if(dx&&x*dx<=5||dy&&y*dy<=5)return;var forward=dx?Math.abs(x):Math.abs(y),cross=dx?Math.abs(y):Math.abs(x);var s=forward+cross*3+(cross>forward?1000:0);if(s<score){score=s;best=el;}});if(best){best.focus();best.scrollIntoView({block:'nearest',inline:'nearest'});}else if(options.indexOf(current)<0&&options[0])options[0].focus();}
